	ida_struct.set_member_cmt(ida_struct.get_member(struc, 311856), '''String: "Select the stop condition, this refers to when the app will stop showing the in-app message to the user. \"none\" means no stop condition, in this case the message will be displayed always (kind of annoying). \"times\" means that the message will be displayed after certain amount of times, example: 1, 2 or 3 times. When selecting \"times\" the \"Max times\" parameter is mandatory. \"confirm\" means that the user needs to confirm or acknowledge the message to dismiss it. When selecting \"confirm\" the \"Max times\" parameter is optional, which means that the user will able to dismiss the dialog and see it n max times even it the user does not confirm or acknowledge it."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 311848), '''AnonymousClosure: (0x985fc4), in [package:sc_app/pages/manifest_tool_in_app_messages/components/condition_view.dart] _MessageConditionViewState::_buildStopCondition (0x985db4)''', True)
