	ida_struct.set_member_cmt(ida_struct.get_member(struc, 311632), '''String: "These are the actions that the user needs to take when presenting the modal. Each button has a title. The title could be an existing string from the catalog or a new bundle of strings; the title is mandatory. You can select \"marked\" or not, this refers to the style of the button. Marked will displayed a red button, usually for \"Cancel\", and not marked will be a blue/regular button. Dismissible refers to the capability to dismiss the modal when the user taps on the button. Confirmable refers to confirm an action that the user needs to take. If you select URL make sure that you can validate the URL by launching it."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 311624), '''String: "For a large modal, you can display multiple pages to the user. Each page should have a title, a message and an image."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 311616), '''String: "Enter the message for the modal. For small modals the message is mandatory. Select the type and enter the key or strings. \"catalog\" refers to the existing strings included in the live app and can be reused by passing a valid key from Lokalise. \"bundle\" refers to a new set of strings that are not included in the live app, you need to pass translated strings for all the supported locales."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 311608), '''String: "Message"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 311600), '''String: "Enter the image for the modal. For small modals the image is optional. Select the type and enter the paths. \"catalog\" refers to the existing images included in the live app and can be reused by passing a valid path to the image. \"cloud\" refers to a new image that is not included in the live app, you need to pass the remote path to be downloaded by the app. You can also pass an specific height and width for the image, if not passed then the image is taking its default size."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 311592), '''String: "Image"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 311584), '''String: "Enter the title for the modal. This parameter is optional."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 311576), '''String: "Title"''', True)
