	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185408), '''String: "Unsere Experten für die Entwicklung von Kindern im Fisher-Price® Play Lab haben uns bei der Entwicklung dieses Ansatzes geholfen, damit Ihr Kind "''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185400), '''String: " für eine weitere Entspannung zu beruhigen."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185392), '''String: "Gedämpftes Licht und sanftere, langsamere Musik helfen, die Sinne von "''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185384), '''String: "MODUS "''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185376), '''String: "Musik: "''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185368), '''String: "Vibration: "''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185360), '''String: "Ja, zurücksetzen"''', True)
