	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185328), '''String: "Vibration nur bei Entspannend"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185320), '''String: "Vibration nach dem ersten Weinen beginnen"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185312), '''String: "Erkennen und entspannen"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185304), '''String: "Erkennen und reagieren"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185296), '''String: "Mehr erfahren\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185288), '''String: "Sehen Sie sich Videos an und erfahren Sie mehr über Luminate Bassinet™ und das Smart Sensing System."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185280), '''String: "Es beruhigt nur mit unserer Wiedergabeliste für Aufmerksamkeit – Beruhigen – Schlafen™. Um das Baby auf das Kinderbett vorzubereiten, reagiert das Beistellbett nicht mehr auf das Weinen und die Vibration kann nicht mehr verwendet werden."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185272), '''String: "Es beruhigt mit der Wiedergabeliste für Aufmerksamkeit – Beruhigen – Schlafen™. Die Reaktion des Beistellbetts auf das Weinen des Babys wird verzögert, um Ihrem Baby Zeit zu geben, sich selbst zu beruhigen zu lernen."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185264), '''String: "Es reagiert auf das Weinen des Babys, indem es automatisch die Lautstärke und die Vibrationen erhöht, um es zu beruhigen."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185256), '''String: "Das Smart Sensing System kann auf das Weinen des Babys reagieren und bietet 3 speziell entwickelte Beruhigungsmodi zur Auswahl an."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185248), '''String: "Videos ansehen"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185240), '''String: "Das Smart Sensing System wurde so konzipiert, dass es nur über die Systemsteuerung des Beistellbetts aktiviert werden kann. So bleibt die Verbindung zwischen Eltern und Baby erhalten und das Baby wird überprüft, bevor das System mit dem Zuhören und Beruhigen beginnt."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185232), '''Closure: (dynamic) => String from Function 'm24': static. (0x703267309a28)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185224), '''String: "Entspannende Geräusche werden abgespielt, um einen dauerhaften Schlaf zu gewährleisten – das Smart Sensing System ist in dieser Phase ganz Ohr!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185216), '''String: "Langsamere Musik hilft, die Sinne des Babys zu entspannen, und hilft ihm, sich weiter zu beruhigen – Das Smart Sensing System ist in dieser Phase ganz Ohr!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185208), '''Closure: (dynamic) => String from Function 'm23': static. (0x7032672f945c)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185200), '''String: "Beruhigende Musik"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185192), '''String: "Möchten Sie erneut starten\? Drücken Sie die Taste für das Smart Sensing System am Beistellbett, um es wieder zu starten."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185184), '''String: "Entspannen ist zu Ende"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185176), '''String: "Aufmerksamkeitsmusik"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185168), '''String: "Um dies einzuschalten, drücken Sie die Taste für das Smart Sensing System am Beistellbett."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185160), '''String: "Psst … Smart Sensing ist ausgeschaltet"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185152), '''Closure: (dynamic) => String from Function 'm22': static. (0x703267309ab4)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185144), '''String: "Modi des Smart Sensing System"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185136), '''Closure: (dynamic) => String from Function 'm21': static. (0x703267309b40)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185128), '''String: "Entspannender Modus"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185120), '''String: "Entspannende Sounds gewährleisten einen dauerhaften Schlaf."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185112), '''String: "Langsamere Musik hilft, die Sinne des Babys zu entspannen und weiter abzuschalten."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185104), '''String: "Die sanfte Musik hilft, die Aufmerksamkeit des Babys zu erregen, und sie gibt ihm ein Zeichen, dass es Zeit fürs Bettchen ist."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185096), '''String: "Das Baby hat geweint und das Beistellbett reagiert ... bleiben Sie dran!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185088), '''String: "Entspannen läuft ..."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185080), '''String: "Das Smart Sensing System ist eingeschaltet und reagiert, wenn das Baby zu weinen beginnt."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185072), '''String: "Zzzzzz …."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185064), '''String: "Baby beruhigen ..."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185056), '''String: "Bereit zum Schlafengehen\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185048), '''String: "Beginnt mit der Wiedergabeliste für „Aufmerksamkeit – Beruhigen – Schlafen™“, die dem Baby helfen soll, von selbst einzuschlafen. Das Beistellbett reagiert auf das Weinen mit Geräuschen und Vibrationen, aber die Reaktion erfolgt verzögert, damit sich das Baby selbst beruhigen kann."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185040), '''String: "Modus 2: Erkennen und entspannen"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185032), '''String: "Bereit zum Beruhigen ..."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185024), '''String: "Es beruhigt Ihr Baby mit Vibration und einem Sound Ihrer Wahl. Wenn das Baby weint, reagiert das Beistellbett mit erhöhter Vibration und Lautstärke, um es zu beruhigen."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185016), '''String: "Modus 1: Erkennen und reagieren"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185008), '''String: "Licht im Beistellbett"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 185000), '''String: "Mehr über Luminate Bassinet™ und das Smart Sensing System erfahren"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184992), '''String: "Licht am Boden und im Beistellbett"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184984), '''String: "Individuelle Entspannung"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184976), '''String: "Finden Sie Ihren Weg (und Ihr Baby!) im Dunkeln mit dem bewegungsaktivierten Bodenlicht und dem Licht im Beistellbett. Schalten Sie es ein oder aus und wählen Sie die Helligkeit."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184968), '''String: "Wählen Sie Ihre eigenen beruhigenden Vorlieben, von Klängen und Musik bis hin zu beruhigenden Vibes. Außerdem können Sie Ihre Favoriten speichern!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184960), '''String: "Das Beistellbett reagiert automatisch auf das Weinen des Babys und verfügt über eine Vielzahl von Beruhigungsoptionen. Wählen Sie aus 3 individuellen Beruhigungsmodi."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184952), '''String: "Willkommen bei Luminate Bassinet™! Wenn es darum geht, Ihr Baby in den Schlaf zu wiegen, haben Sie einige Optionen zur Auswahl. Außerdem gibt es einige tolle Beleuchtungsfunktionen, die Sie sich ansehen sollten!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184944), '''String: "Mehr über Luminate Bassinet™ erfahren"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184936), '''String: "FP Entspannen"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184928), '''String: "Sieht aus, als würden Ihnen diese Einstellungen so sehr gefallen, dass Sie sie zweimal speichern wollten – hoppla! Vor dem Speichern eines neuen Favoriten sind Änderungen erforderlich."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184920), '''String: "Sie sind dabei, den bisherigen Favoriten zu überschreiben, ist das in Ordnung\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184912), '''String: "Es sieht nicht so aus, als ob für diesen Favoriten schon etwas gespeichert ist."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184904), '''String: "Beistellbett anpassen"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184896), '''String: "Smart Sensing System anpassen"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184888), '''String: "Beruhigt das Baby mit der Wiedergabeliste von „Aufmerksamkeit – Beruhigen – Schlafen™“. Das Beistellbett reagiert nicht mehr und die Vibrationsfunktion ist ausgeschaltet, um das Baby von diesen beruhigenden Funktionen zu entwöhnen."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184880), '''String: "Modus 3: Aufmerksamkeit – Beruhigen – Schlafen™"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184872), '''String: "Was ist „Schlafphasen“\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184864), '''String: "Dritte Phase: Schlafen"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184856), '''String: "Zweite Phase: Entspannen"''', True)
