	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184840), '''String: "Ein sanftes Nachtlicht und Soundeffekte wie rosa Rauschen oder Naturgeräusche tragen zu einem ruhigen Schlaf bei."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184832), '''Closure: (dynamic) => String from Function 'm20': static. (0x703267309bcc)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 184824), '''String: "Kennen Sie das Gefühl, wenn Ihr Baby noch nicht ganz bereit zum Schlafen ist\? In dieser Phase helfen die bezaubernden Lichter und die sanfte Musik des Beruhigers, die Aufmerksamkeit Ihres Kleinen zu erregen."''', True)
