	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182496), '''String: "Sieht aus, als wären Sie neu hier! Richten wir das Lumalou so ein, wie Sie es gerne hätten. Bereit\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182488), '''String: "Wochenplan"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182480), '''String: "Bearbeiten Sie Ihre Zeiten oder behalten Sie sie so, wie sie sind, und die Funktion Schlaftrainer wird wieder aufgenommen, sobald die Routine beendet ist!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182472), '''String: "Ihr Schlaftrainer und die routinemäßige Startzeit überschneiden sich hier:"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182464), '''String: "Drücken Sie auf die Fernbedienung oder tippen Sie hier, um zu beginnen!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182456), '''String: "Aufgaben"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182448), '''String: "Aufgabenname erforderlich"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182440), '''String: "Es existiert offensichtlich bereits eine Aufgabe mit diesem Namen."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182432), '''String: "Aufgabenmusik"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182424), '''String: "Es muss mindestens eine Aufgabe hinzugefügt werden."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182416), '''String: "Tippen Sie zum erneuten Aktivieren auf „Bearbeiten“."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182408), '''String: "Alarm beenden"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182400), '''String: "Routine starten um"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182392), '''String: "Kein Plan"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182384), '''String: "Bevor Sie Ihre Einstellungen bearbeiten können, muss das Lumalou schlafen. Beginnen Sie ein Nickerchen und ... pssst ... dann geht die Steuerung ganz auf Sie über."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182376), '''String: "Möchten Sie mehr darüber erfahren, wie Sie Lumalou als Einschlafhilfe und Schlaftrainer einsetzen können\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182368), '''String: "Sobald die Wach- und Schlafzeiten eingestellt sind, färbt sich Lumalou rot, wenn es Zeit ist, im Bett zu bleiben, oder grün, wenn es in Ordnung ist, aufzustehen, wenn Kinder die Fernbedienung drücken."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182360), '''String: "Der Schlaftrainer hilft den Kindern zu wissen, wann sie im Bett bleiben sollen und wann sie aufstehen dürfen! Sie können für jeden Wochentag unterschiedliche Schlaf- und Wachzeiten eingeben oder den gleichen Zeitplan auf alle anwenden."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182352), '''String: "Sobald Sie die Einstellungen personalisiert haben, können Sie sofort mit der Entspannung beginnen, indem Sie auf die Schaltfläche „Entspannung starten“ tippen oder auf die Fernbedienung drücken."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182344), '''Closure: (dynamic) => String from Function 'm7': static. (0x70326730a36c)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182336), '''String: "Lumalou wird alle Aufgaben in der Routine mit Lichtsignalen darstellen. Um zu beginnen, drücken Sie die Fernbedienung und die erste Aufgabe erscheint. Nachdem die Aufgabe abgeschlossen ist, drücken Sie die Fernbedienung, um Belohnungen zu erhalten und die Routine fortzusetzen!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182328), '''String: "Planung Ihrer Routine"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182320), '''String: "Wählen Sie die Tage und wählen Sie eine Startzeit. Nach dem Speichern beginnt Lumalou die Routine automatisch zur geplanten Zeit und am geplanten Tag."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182312), '''String: "Eine Routine erstellen"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182304), '''String: "Lumalou verfügt über 11 Aufgaben, aus denen Sie wählen können, um eine schrittweise Schlafenszeitroutine zusammenzustellen, die für Sie und Ihr Kind am besten funktioniert!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182296), '''String: "Routinen sind derzeit deaktiviert."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182288), '''String: "Möchten Sie mehr darüber erfahren, wie Sie Lumalou als Routine-Hilfsmittel einsetzen können\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182280), '''String: "Aufgaben umbenennen"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182272), '''String: "ROUTINENAME"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182264), '''String: "Routinename erforderlich"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182256), '''String: "Routine-Musik-Individualisierung"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182248), '''String: "Bestehende Routine ersetzen\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182240), '''String: "Es wurde bereits eine Routine für diesen Tag gewählt. Möchten Sie stattdessen diese Routine verwenden\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182232), '''String: "Routinen sind derzeit deaktiviert. Tippen Sie zum Aktivieren."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182224), '''String: "Routine erfolgreich abgeschlossen!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182216), '''String: "Es existiert bereits eine Routine mit diesem Namen."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182208), '''String: "Routine entfernen\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182200), '''String: "Wenn Sie fortfahren, wird sie von allen Tagen gelöscht, an denen sie angewendet wurde."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182192), '''String: "Nun, da der Schlaftrainer Ihres Kindes eingerichtet ist, können Sie im Tagesmodus den Mittagsschlaf beginnen, indem Sie den Mittagsschlaf-Schalter auf der Rückseite der Fernbedienung drücken!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182184), '''String: "Nachdem Sie nun eine Routine eingerichtet haben, können Sie eine dem aktuellen Tag zugeordnete Routine aktivieren, indem Sie den Routine-Schalter auf der Rückseite der Fernbedienung drücken."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182176), '''String: "Lumalou befindet sich derzeit im Nachtmodus. Wenn Sie eine Routine starten, wechselt Lumalou in den Routine-Modus. Es kehrt in den Nachtmodus zurück, wenn der Routine-Modus beendet ist."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182168), '''String: "Ja, Routine starten"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182160), '''Closure: (dynamic) => String from Function 'm6': static. (0x70326730a404)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182152), '''String: "Gegenwärtig lässt Lumalou nur eine Routine pro Tag zu. Um zu sehen, wie Sie Lumalou sowohl für Morgen- als auch für Abendroutinen verwenden können, lesen Sie bitte die FAQs."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182144), '''String: "12 ist die maximale Anzahl von Aufgaben, die Sie hinzufügen können. Zum Hinzufügen weiterer Aufgaben entfernen Sie mindestens eine Aufgabe."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182136), '''String: "Sie können maximal 14 Routinen hinzufügen. Um weitere Routinen hinzuzufügen, müssen Sie mindestens eine Routine entfernen."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182128), '''String: "Es sieht so aus, als müsste zuerst etwas repariert werden."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182120), '''String: "Lumalou™ System für besseres Einschlafen"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182112), '''String: "Auf diese Weise wird die Routine für Lumalou beendet."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182104), '''String: "Sind Sie bereit, Lumalou (und Ihr Kind) mit einer Routine zu versehen\? Klicken Sie unten, um mit der Individualisierung einer Routine mit eigenen Aufgaben und Zeiten zu beginnen, die für Sie am besten geeignet sind!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182096), '''String: "Brauchen Sie eine Pause\? Kein Problem. Dadurch werden Ihre Routinen nicht gelöscht, sondern nur angehalten, bis Sie wieder bereit sind."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182088), '''String: "Das ist jetzt kein guter Zeitpunkt ..."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182080), '''String: "Wir befinden uns mitten in einer Routine, aber sobald diese abgeschlossen ist, können diese Änderungen vorgenommen werden. Danke!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 182072), '''String: "Nur eine Sekunde! Sobald wir diese Routine abgeschlossen haben, können Sie alles weiter bearbeiten!"''', True)
