	ida_struct.set_member_cmt(ida_struct.get_member(struc, 177192), '''String: "Before you can edit your settings, Lumalou has to be snoozing. Start a nap…shhh…then those controls are all yours."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 177184), '''String: "Want to learn more about how to use Lumalou as a Soother and Sleep Trainer\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 177176), '''String: "Once Wake and Sleep times are set, Lumalou will turn red if it\'s time to stay in bed or green when it\'s okay to get up when kids press the remote."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 177168), '''String: "The Sleep Trainer helps kids know when to stay in bed and when it\'s okay to get up! You can enter different Sleep and Wake times for each day of the week or apply the same schedule to them all."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 177160), '''String: "Once you\'ve personalized the settings, you can start soothing right away by tapping the “Start Soothing“ button or by pressing on the remote."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 177152), '''Closure: (dynamic) => String from Function 'm7': static. (0x7032672f9cc0)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 177144), '''String: "Lumalou will illuminate all the tasks in the routine. To begin, press the remote and the first task appears. After completing the task, press the remote for fun rewards and to advance the routine!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 177136), '''String: "Scheduling Your Routine"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 177128), '''String: "Select the days and choose a start time. Once saved, Lumalou will automatically begin the routine at the scheduled time and day."''', True)
