	ida_struct.set_member_cmt(ida_struct.get_member(struc, 175144), '''String: "Mira los vídeos para obtener más información sobre Luminate Bassinet™ y el sistema de detección inteligente."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 175136), '''String: "Relaja solo con nuestra lista de reproducción Preparados, Listos, Dormir™. Para que tu bebé se prepare para dormir (¡hurra!), la cuna deja de responder al llanto y ya no se puede usar la vibración."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 175128), '''String: "Relaja con nuestra lista de reproducción Preparados, Listos, Dormir™. La respuesta de la cuna al llanto de tu bebé se retrasa para darle tiempo a que aprenda a relajarse por su cuenta."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 175120), '''String: "Responde al llanto de tu bebé y aumenta automáticamente el volumen y la vibración para que se relaje."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 175112), '''String: "El sistema de detección inteligente responde al llanto de tu bebé y ofrece 3 modos de relajación especialmente diseñados."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 175104), '''String: "Mira los vídeos"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 175096), '''String: "El sistema de detección inteligente está cuidadosamente diseñado para activarse solo desde el panel de control de la cuna. Así se garantiza que padres y bebés estén unidos, pues se controla al bebé antes de que el sistema empiece el proceso de escucha y relajación."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 175088), '''Closure: (dynamic) => String from Function 'm24': static. (0x7032672d8924)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 175080), '''String: "Suenan sonidos relajantes para ayudar a mantener un sueño constante. Nota: el sistema de detección inteligente es muy perceptivo en esta fase."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 175072), '''String: "La música más lenta ayuda a relajar los sentidos de tu bebé para que se vaya adormilando. Nota: el sistema de detección inteligente es muy perceptivo en esta fase."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 175064), '''Closure: (dynamic) => String from Function 'm23': static. (0x7032672d89e8)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 175056), '''String: "Música fase Listos"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 175048), '''String: "¿Quieres volver a empezar\? Pulsa el botón del sistema de detección inteligente que hay en la cuna para reiniciarlo."''', True)
