	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174968), '''String: "La música más lenta ayuda a relajar los sentidos de tu bebé para que se vaya adormilando."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174960), '''String: "La música suave capta la atención de tu bebé y le va avisando de que es hora de irse a dormir."''', True)
