	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174912), '''String: "Empieza con la lista de reproducción Preparados, Listos, Dormir™, diseñada para que tu bebé coja el sueño sin ayuda. La cuna responde a los llantos con sonido y vibración, pero la respuesta se retrasa para que se relaje por su cuenta."''', True)
