	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174896), '''String: "Relaja a tu bebé con la vibración y el sonido que elijas. Si llora, la cuna responde aumentando la vibración y el volumen para que se relaje."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174888), '''String: "Luz en la cuna"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174880), '''String: "Más información sobre Luminate Bassinet™ y el sistema de detección inteligente"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174872), '''String: "Luces de suelo y en la cuna"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174864), '''String: "Relajación personalizable"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174856), '''String: "Encuentra tu camino ─y a tu bebé─ en la oscuridad con las luces de suelo y en la cuna, que tienen sensor de movimiento. Actívalas o desactívalas y selecciona el brillo."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174848), '''String: "Elige tus propias preferencias de relajación, desde sonidos y música hasta vibraciones calmantes. ¡Y puedes guardar tus favoritos!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174840), '''String: "La cuna responde automáticamente a los llantos de tu bebé con una serie de opciones relajantes. Puedes elegir entre 3 modos de relajación personalizados."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174832), '''String: "Te damos la bienvenida a Luminate Bassinet™. Puedes elegir entre diversas opciones para que tu bebé se relaje y se duerma. Además, hay un montón de cuidadas funciones de iluminación."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174824), '''String: "Más información sobre Luminate Bassinet"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174816), '''String: "Parece que esta configuración te gusta tanto que querías guardarla dos veces... ¡Ahí va! Haz unos cambios antes de guardar un nuevo favorito."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174808), '''String: "Estás a punto de sobrescribir un favorito anterior. ¿Quieres continuar\?"''', True)
