	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174784), '''String: "Personalizar el sistema de detección inteligente"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174776), '''String: "Relaja a tu bebé con la lista de reproducción Preparados, Listos, Dormir™. La cuna deja de responder y la vibración se desactiva para que se deshabitúe de estas funciones relajantes."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174768), '''String: "Modo 3: Preparados, Listos, Dormir™"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174760), '''String: "Tercera fase: Dormir"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174752), '''String: "La suave luz nocturna y los efectos de sonido que elijas, como el ruido rosa o los sonidos de la naturaleza, mantendrán el sueño sin interrupciones."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174744), '''Closure: (dynamic) => String from Function 'm20': static. (0x7032672e91f4)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 174736), '''String: "A veces, a tu peque aún le quedan energías. Durante esta fase, las cautivadoras luces y la relajante música de este producto llamarán la atención de tu bebé."''', True)
