	ida_struct.set_member_cmt(ida_struct.get_member(struc, 173696), '''String: "Lumalou está ahora mismo en el modo Hora de dormir. Si inicias la rutina, Lumalou entrará en el modo Rutina. Se reanudará el modo Hora de dormir cuando finalice el modo Rutina."''', True)
