	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172592), '''String: ". Nuestros expertos en el desarrollo infantil de Fisher-Price® Play Lab nos ayudaron a crear este método que ayudará a tu bebé a dormir por la noche."''', True)
