	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172448), '''String: "Mira videos y conoce más sobre Luminate Bassinet™ y el Sistema de detección inteligente."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172440), '''String: "Relaja a tu bebé solo con nuestra lista de reproducción Listo, Calmar, Dormir™. Para preparar al bebé para ir a su cuna principal (¡yupi!), ya no hay respuesta ante el llanto y la vibración ya no puede usarse."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172432), '''String: "Relaja a tu bebé con nuestra lista de reproducción Listo, Calmar, Dormir™. La respuesta de la cuna ante el llanto del bebé se activa un poco después para darle tiempo al bebé de relajarse por sí mismo."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172424), '''String: "Cuando el bebé llora, el volumen y la vibración aumentan automáticamente para ayudar a relajarlo."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172416), '''String: "El Sistema de detección inteligente responde al llanto del bebé y ofrece 3 modos especialmente diseñados para la relajación."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172408), '''String: "Mira videos"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172400), '''String: "El Sistema de detección inteligente fue diseñado cuidadosamente para que solo pudiera activarse desde el panel de control de la cuna, con la finalidad de asegurar que la madre o el padre y el bebé permanecieran conectados, y que el bebé estuviera bajo supervisión adulta antes de que el sistema comenzara a escuchar y relajar."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172392), '''Closure: (dynamic) => String from Function 'm24': static. (0x7032672d8898)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172384), '''String: "Reproduce sonidos relajantes para ayudar a mantener un sueño constante. (El Sistema de detección inteligente está alerta en esta etapa)."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172376), '''String: "La música más lenta ayuda a relajar los sentidos del bebé para tranquilizarlo aún más. (El Sistema de detección inteligente está alerta en esta etapa)."''', True)
