	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172176), '''String: "Relaja a tu bebé con las vibraciones y los sonidos que tú elijas. Si el bebé llora, la cuna responde con más vibraciones y mayor volumen para ayudar a calmarlo."''', True)
