	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172128), '''String: "Guíate (¡y encuentra tu bebé!) en la oscuridad con la luz de piso que se activa con el movimiento y la luz de la cuna. Podrás encenderlas y apagarlas, así como ajustar su brillo."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172120), '''String: "Elige tus propias preferencias de relajación, desde sonidos y música, hasta vibraciones tranquilizadoras. ¡Además, podrás guardar tus favoritas!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172112), '''String: "La cuna responde automáticamente al llanto del bebé con una variedad de opciones de relajación. Elige entre 3 modos de relajación personalizados."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 172104), '''String: "¡Te damos la bienvenida a tu Luminate Bassinet™! Encontrarás varias opciones para relajar a tu bebé hasta que se duerma, ¡así como algunos ajustes de iluminación geniales!"''', True)
