	ida_struct.set_member_cmt(ida_struct.get_member(struc, 169376), '''String: "Una vez que hayas establecido los horarios de dormir y despertar, cuando los niños presionen el control, Lumalou se encenderá con una luz roja si es hora de dormir o con una luz verde si es hora de despertar."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 169368), '''String: "¡El Entrenador del sueño ayuda a los niños a saber cuándo irse a dormir y cuándo es momento de despertar! Puedes programar diferentes horarios para dormir y despertar de acuerdo con el día de la semana o establecer el mismo horario para todos los días."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 169360), '''String: "Una vez que hayas personalizado los ajustes, puedes comenzar a calmar a tu bebé de inmediato con el botón \"Activar apaciguador\" o al presionar el control."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 169352), '''Closure: (dynamic) => String from Function 'm7': static. (0x7032672d9458)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 169344), '''String: "Lumalou iluminará todas las tareas en la rutina. Para comenzar, presiona el control y aparecerá la primera tarea. Después de completar la tarea, ¡presiona el control para obtener recompensas divertidas y continuar con la rutina!"''', True)
