	ida_struct.set_member_cmt(ida_struct.get_member(struc, 167008), '''String: "Apaise uniquement avec notre liste de lecture Ready, Settle, Sleep™. Pour aider à préparer bébé au lit de bébé (youpi !), le couffin ne répond plus aux pleurs et la vibration ne peut plus être utilisée."''', True)
