	ida_struct.set_member_cmt(ida_struct.get_member(struc, 162240), '''String: "L\'entraînement au sommeil permet d\'indiquer à l\'enfant quand il doit rester au lit et quand il peut se lever ! Pour commencer, sélectionnez « Configurer l\'entraînement au sommeil »."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 162232), '''String: "S\'apaiser sur demande"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 162224), '''String: "Une fois que vous avez personnalisé les paramètres, vous pouvez lancer l\'option d\'apaisement directement en appuyant sur le bouton « Lancer l\'apaisement » ou sur le ventre du lapin."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 162216), '''String: "Vous pouvez personnaliser les options de lumière, de musique et de son et configurer les préférences du minuteur à partir de la zone Commandes."''', True)
