	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161560), '''String: "Guarda i video e scopri di più su Luminate Bassinet™ e sul sistema di rilevamento smart."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161552), '''String: "Rilassa solo con la nostra playlist Preparazione, calma, sonno™. Per preparare il bambino a dormire nella culla vera e propria (urrà!), il dispositivo non risponde più al pianto e la vibrazione non può più essere utilizzata."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161544), '''String: "Rilassa con la nostra playlist Preparazione, calma, sonno™. La risposta della culla al pianto del bambino viene ritardata in modo da permettergli di imparare a rilassarsi da solo."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161536), '''String: "Risponde al pianto del bambino aumentando automaticamente il volume e le vibrazioni per aiutarlo a rilassarsi."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161528), '''String: "Il sistema di rilevamento smart può rispondere al pianto del bambino e offre tre modalità di rilassamento tra cui scegliere, programmate appositamente."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161520), '''String: "Guarda i video"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161512), '''String: "Il sistema di rilevamento smart è stato progettato con cura per essere attivato solo dal pannello di controllo della culla. Ciò garantisce che il genitore e il bambino restino connessi e che il bambino venga controllato prima che il sistema inizi ad ascoltare e a rilassare."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161504), '''Closure: (dynamic) => String from Function 'm24': static. (0x7032672b790c)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161496), '''String: "I suoni rilassanti aiutano a stabilizzare il sonno (il sistema di rilevamento smart è tutto orecchi in questa fase)."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161488), '''String: "La musica lenta rilassa i sensi del bambino, aiutandolo ad addormentarsi (il sistema di rilevamento smart è tutto orecchi in questa fase)."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161480), '''Closure: (dynamic) => String from Function 'm23': static. (0x7032672b7998)''', True)
