	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161384), '''String: "La musica lenta rilassa i sensi del bambino, aiutandolo ad addormentarsi."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161376), '''String: "La musica tranquilla cattura l\'attenzione del bambino e lo aiuta a capire che è ora di fare la nanna."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161368), '''String: "È stato rilevato il pianto del bambino e la culla sta rispondendo... Restare sintonizzati."''', True)
