	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161352), '''String: "Il sistema di rilevamento smart è attivo e risponde se il bambino si mette a piangere."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161344), '''String: "Rilassamento bambino..."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161336), '''String: "Pronti per la nanna\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161328), '''String: "Sistema di rilevamento smart"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161320), '''String: "Inizia con la playlist Preparazione, calma, sonno™, pensata per aiutare il bambino ad addormentarsi da solo. La culla reagisce al pianto con suoni e vibrazioni, ma la risposta viene ritardata in modo da permettere al bambino di rilassarsi da solo."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161312), '''String: "Modalità 2: Rilevamento e rilassamento"''', True)
