	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161248), '''String: "Orientati (e trova il tuo bambino!) al buio grazie alle luci nella culla e da pavimento, dotate di sensori di movimento. Attivale, disattivale o seleziona la luminosità."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161240), '''String: "Seleziona le tue preferenze di relax tra suoni, musica e vibrazioni rilassanti. E salva le tue preferite!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161232), '''String: "La culla risponde automaticamente al pianto del bambino con tante opzioni di rilassamento. Scegli fra tre modalità relax personalizzate."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161224), '''String: "Ti diamo il benvenuto alla tua Luminate Bassinet™! Hai diverse opzioni tra cui scegliere per fare addormentare il tuo bambino, e alcune fantastiche funzioni di luce da sperimentare!"''', True)
