	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161160), '''String: "Rilassa il bambino con la playlist Preparazione, calma, sonno™. La culla non risponde più e la vibrazione è disattivata per aiutare il bambino a separarsi dalle funzioni di rilassamento."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161152), '''String: "Modalità 3: Preparazione, calma, sonno™"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 161144), '''String: "Che cos\'è Fasi del sonno\?"''', True)
