	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156840), '''String: "È la tua prima volta qui! Configuriamo questo dolce coniglietto come preferisci. Vuoi iniziare\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156832), '''String: "Sapevi che il coniglietto è un accessorio per il rilassamento e un assistente di sonno\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156824), '''String: "Quando premono la pancia del coniglietto, i bambini ottengono un esito diverso a seconda del momento della giornata. Giorno: la pancia diventa verde, è ora di alzarsi! Notte e pisolino: la pancia diventa rossa, restare a letto!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156816), '''String: "L\'assistente di sonno aiuta i bambini a capire quando restare a letto e quando è ora di alzarsi! Per iniziare, seleziona \"Configura assistente di sonno\"."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156808), '''String: "Relax a richiesta"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156800), '''String: "Una volta che avrai personalizzato le impostazioni, potrai iniziare subito il relax toccando il pulsante \"Inizia relax\" o premendo la pancia del coniglietto."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156792), '''String: "Nell\'area dei comandi puoi personalizzare luci, musica e suoni e impostare le preferenze per il timer."''', True)
