	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156456), '''String: " — połączono!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156448), '''String: ". Edytuj czas rozpoczęcia rutyny lub czas trwania drzemki, aby uniknąć nakładania się zdarzeń w czasie. Miłej drzemki!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156440), '''String: "Ta drzemka będzie nakładać się na zaplanowaną rutynę, która rozpoczyna się o "''', True)
