	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156320), '''String: " nie będzie mieć problemów ze snem. Nasi eksperci od rozwoju dziecka z laboratorium zabawy Fisher-Price® pomogli nam opracować rozwiązanie, dzięki któremu Twoje dziecko szybciej zaśnie."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156312), '''String: "Etapy zasypiania to narzędzie, dzięki któremu "''', True)
