	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156208), '''String: "Detekcja i uspokajanie"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156200), '''String: "Detekcja i reakcja"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156192), '''String: "Chcesz dowiedzieć się więcej\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156184), '''String: "Luminate Bassinet™ i inteligentny system detekcji — obejrzyj filmy i dowiedz się więcej."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156176), '''String: "Uspokaja dziecko jedynie za pomocą listy odtwarzania Przygotowanie, Uspokojenie, Sen. Aby przygotować dziecko do korzystania z większego łóżeczka (super!), system nie będzie już reagował na płacz i tło dźwiękowe nie będzie odtwarzane."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156168), '''String: "Płacz dziecka ukoi lista odtwarzania Przygotowanie, Uspokojenie, Sen. Reakcje łóżeczka na płacz dziecka następują z opóźnieniem, by dać mu czas na naukę samodzielnego uspokajania się."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156160), '''String: "Reaguje na płacz dziecka, automatycznie zwiększając głośność tła dźwiękowego, co pomaga uspokoić dziecko."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156152), '''String: "Inteligentny system detekcji reaguje na płacz dziecka i oferuje 3 dedykowane tryby uspokajania."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156144), '''String: "Obejrzyj filmy"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156136), '''String: "Inteligentny system detekcji został starannie zaprojektowany w taki sposób, aby można go było aktywować wyłącznie za pomocą panelu sterowania łóżeczka. Dzięki temu rodzic ma stałą łączność z dzieckiem oraz pewność, że wszystko jest w porządku, zanim system zacznie nasłuchiwać i uspokajać dziecko."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156128), '''Closure: (dynamic) => String from Function 'm24': static. (0x7032672a71f4)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156120), '''String: "Urządzenie odtwarza kojące dźwięki, by umożliwić Twojemu dziecku spokojny sen. (P.S. Inteligentny system detekcji nasłuchuje wtedy bardzo uważnie)."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156112), '''String: "Wolniejsze utwory koją zmysły dziecka i pomagają w dalszym rozluźnieniu się. (P.S. Inteligentny system detekcji nasłuchuje wtedy bardzo uważnie)."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156104), '''Closure: (dynamic) => String from Function 'm23': static. (0x7032672a7280)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156096), '''String: "Muzyka Uspokojenie"''', True)
