	ida_struct.set_member_cmt(ida_struct.get_member(struc, 156000), '''String: "Subtelna muzyka przykuwa uwagę dziecka i daje mu sygnał, że przyszła pora na sen."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 155992), '''String: "Słychać było płacz dziecka, łóżeczko zareagowało... i wszystko gra."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 155984), '''String: "Trwające zadanie: uspokajanie..."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 155976), '''String: "Inteligentny system detekcji jest włączony i będzie reagował na płacz dziecka."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 155968), '''String: "Zzzzzz…."''', True)
