	ida_struct.set_member_cmt(ida_struct.get_member(struc, 155944), '''String: "Inteligentny system detekcji"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 155936), '''String: "Rozpoczyna się listą odtwarzania Przygotowanie, Uspokojenie, Sen, która ma za zadanie wspomóc samodzielne zasypianie dziecka. Łóżeczko zareaguje na płacz dziecka, odtwarzając dźwięk lub tło dźwiękowe, ale z opóźnieniem, aby dać dziecku szansę na samodzielne uspokojenie się."''', True)
