	ida_struct.set_member_cmt(ida_struct.get_member(struc, 155912), '''String: "Uspokaja dziecko za pomocą tła dźwiękowego i wybranego dźwięku. Jeśli dziecko zacznie płakać, łóżeczko zareaguje automatycznie, zwiększając głośność tła dźwiękowego, by uspokoić dziecko."''', True)
