	ida_struct.set_member_cmt(ida_struct.get_member(struc, 155864), '''String: "Dzięki aktywowanemu ruchem podświetleniu podłogi i łóżeczka, odnajdziesz drogę (i dziecko!) nawet w ciemności."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 155856), '''String: "Zdecyduj, jakie opcje uspokajania podobają Ci się najbardziej — od dźwięków i muzyki po uspokajające tła dźwiękowe. Możesz także zapisać je jako ulubione!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 155848), '''String: "Łóżeczko automatycznie reaguje na płacz dziecka, uruchamiając rozmaite funkcje uspokajania. Wybierać można spośród 3 własnych trybów uspokajania."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 155840), '''String: "Przestawiamy łóżeczko Luminate Bassinet™! Oferuje ono wiele opcji usypiania dziecka oraz ciekawe funkcje świetlne!"''', True)
