	ida_struct.set_member_cmt(ida_struct.get_member(struc, 155816), '''String: "Wygląda na to, że tak bardzo lubisz te ustawienia, że próbujesz je zapisać dwukrotnie — ups! Aby zapisać nowe ulubione ustawienie, należy wprowadzić zmiany."''', True)
