	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153144), '''String: "Zanim wprowadzisz ustawienia, urządzenie Lumalou musi przejść w tryb drzemki. Rozpocznij drzemkę... Ciii... Teraz możesz ustawić urządzenie."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153136), '''String: "Chcesz dowiedzieć się więcej o korzystaniu z funkcji Uspokajacz i Trener snu urządzenia Lumalou\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153128), '''String: "Jeśli czasy przebudzenia i snu są ustawione, to gdy dziecko naciśnie przycisk pilota, światło urządzenia Lumalou zaświeci na czerwono, jeśli nadal trwa czas snu, lub na zielono, jeśli jest już pora wstawania."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153120), '''String: "Trener snu podpowiada dziecku, kiedy ma leżeć w łóżeczku, a kiedy już pora wstać. Możesz ustawić różne pory snu i wstawania dla poszczególnych dni tygodnia lub zastosować wspólny harmonogram dla wszystkich."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153112), '''String: "Po spersonalizowaniu ustawień możesz od razu rozpocząć kojenie, dotykając przycisku „Rozpocznij kojenie” lub naciskając przycisk pilota."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153104), '''Closure: (dynamic) => String from Function 'm7': static. (0x7032672a7ba8)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153096), '''String: "Wszystkie zadania programu zostaną podświetlone. Aby rozpocząć, naciśnij przycisk pilota, a wtedy pojawi się pierwsze zadanie. Po wykonaniu zadania naciśnij przycisk pilota. Spowoduje to udostępnienie zabawnych nagród i przejście do kolejnych kroków programu."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153088), '''String: "Harmonogram rutyny"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153080), '''String: "Wybierz dni i godzinę rozpoczęcia. Po zapisaniu urządzenie Lumalou będzie automatycznie rozpoczynać rutynę w zaplanowane dni o ustalonej godzinie."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153072), '''String: "Utwórz rutynę"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153064), '''String: "Urządzenie Lumalou oferuje 11 zadań do wyboru, z których stworzysz rutynę przed snem najlepszą dla Ciebie i Twojego dziecka!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153056), '''String: "Rutyny są obecnie wyłączone."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153048), '''String: "Chcesz dowiedzieć się więcej o korzystaniu z urządzenia Lumalou do kształtowania rutyny przedsennej\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153040), '''String: "Zmień nazwy zadań"''', True)
