	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153024), '''String: "Nazwa rutyny jest wymagana."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153016), '''String: "Dostosowanie muzyki w rutynach"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153008), '''String: "Czy zastąpić istniejącą rutynę\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 153000), '''String: "Dla tego dnia jest już zapisana rutyna. Czy chcesz ją zastąpić\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152992), '''String: "Rutyny są obecnie wyłączone. Stuknij, by włączyć."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152984), '''String: "Udało się ukończyć rutynę!"''', True)
