	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152960), '''String: "Spowoduje to usunięcie rutyny dla wszystkich dni, w których jest ona stosowana."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152952), '''String: "Po skonfigurowaniu Trenera snu możesz rozpocząć drzemkę w trybie Dzień, naciskając przycisk drzemki na odwrocie pilota."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152944), '''String: "Po skonfigurowaniu rutyny możesz aktywować rutynę przypisaną do bieżącego dnia, naciskając przycisk rutyny na odwrocie pilota."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152936), '''String: "Lumalou działa obecnie w trybie Noc. Jeśli rozpoczniesz rutynę, nastąpi przełączenie na tryb Rutyna. Po zakończeniu rutyny tryb Noc zostanie wznowiony."''', True)
