	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152912), '''String: "Obecnie w urządzeniu Lumalou możliwe jest zaplanowanie tylko jednej rutyny na dzień. Z sekcji Najczęściej zadawane pytania dowiesz się, jak korzystać z urządzenia Lumalou zarówno rano, jak i przy zasypianiu."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152904), '''String: "Możesz dodać maksymalnie 12 zadań. Przed dodaniem kolejnego zadania usuń jedno z dotychczasowych."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152896), '''String: "Możesz dodać maksymalnie 14 rutyn. Przed dodaniem kolejnej rutyny usuń jedną z dotychczasowych."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152888), '''String: "Wygląda na to, że najpierw trzeba coś poprawić."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152880), '''String: "System usprawniania rutyn zasypiania Lumalou™"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152872), '''String: "Spowoduje to zakończenie rutyny w urządzeniu Lumalou."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152864), '''String: "Czy chcesz ustawić w urządzeniu Lumalou rutynę dla swojego dziecka\? Wystarczy, że klikniesz poniżej, aby zacząć dostosowywać zadania i najdogodniejsze godziny!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152856), '''String: "Potrzebujesz przerwy\? Nic prostszego. Możesz wstrzymać odtwarzanie rutyny na wybrany okres. Nie spowoduje to usunięcia zapisanych rutyn."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152848), '''String: "To nie najlepsza pora..."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152840), '''String: "Teraz trwa rutyna, ale możesz wprowadzić te zmiany po jej zakończeniu. Dzięki!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152832), '''String: "Jeszcze chwilkę! Po zakończeniu bieżącej rutyny możesz wprowadzać zmiany."''', True)
