	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152816), '''String: "Ten produkt wymaga 4 baterii AA."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152808), '''String: "Niski poziom naładowania baterii. Wymień baterie, a następnie otwórz aplikację, aby ponownie połączyć się z ustawieniami."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152800), '''String: "Niskie"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152792), '''String: "Ze względów bezpieczeństwa po kolejnym zalogowaniu się konieczne będzie ponowne sparowanie z produktami."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152784), '''String: "Wyloguj"''', True)
