	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152768), '''String: "Wykrywanie znajdujących się w pobliżu zgodnych produktów, ich parowanie i sterowanie nimi za pomocą aplikacji Fisher-Price® Smart Connect™ wymaga udzielenia tej aplikacji uprawnień do używania lokalizacji oraz połączenia Bluetooth. Dane lokalizacji są sprawdzane nawet wówczas, gdy aplikacja jest zamknięta lub nie jest w użyciu, jednak dane te nie są przechowywane."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152760), '''String: "Zezwolenie na dostęp do lokalizacji"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152752), '''String: "Funkcja określania lokalizacji jest wyłączona. Dotknij, aby ją włączyć."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 152744), '''String: "Usługa lokalizacji jest wyłączona. Czy chcesz ją włączyć\? Aby włączyć funkcję Bluetooth wymaganą przez wszystkie produkty, należy zezwolić na korzystanie z lokalizacji. Nie wykorzystujemy ani nie zapisujemy danych lokalizacyjnych."''', True)
