	ida_struct.set_member_cmt(ida_struct.get_member(struc, 151304), '''String: "Po naciśnięciu brzuszek króliczka zostanie odpowiednio podświetlony w zależności od pory dnia. Dzień: brzuszek świeci na zielono, można wstawać! Noc i drzemka: brzuszek świeci na czerwono, leżymy dalej!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 151296), '''String: "Trener snu mówi dziecku, kiedy ma leżeć w łóżku, a kiedy może już wstać. Aby rozpocząć korzystanie, wybierz opcję „Ustaw Trenera snu”."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 151288), '''String: "Ukojenie na życzenie"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 151280), '''String: "Po spersonalizowaniu ustawień możesz od razu rozpocząć kojenie, dotykając przycisku „Rozpocznij kojenie” lub naciskając brzuszek króliczka."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 151272), '''String: "W obszarze Ustawienia możesz spersonalizować ustawienia świateł, muzyki i dźwięku, a także preferencje czasomierza."''', True)
