	ida_struct.set_member_cmt(ida_struct.get_member(struc, 150656), '''String: "Videoları izleyerek Luminate Bassinet™ ve Akıllı Algılama Sistemi hakkında daha fazla bilgi edin."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 150648), '''String: "Sadece Hazırlık, Sakinleşme, Uyku™ çalma listemizle sakinleştirir. Bebeği beşiğe hazırlamaya yardımcı olmak için (oley!) beşik artık ağlamaya tepki vermez ve titreşim artık kullanılamaz."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 150640), '''String: "Hazırlık, Sakinleşme, Uyku™ oynatma listemizle sakinleştirir. Beşiğin, bebeğin ağlamasına tepkisi bebeğin kendi kendini sakinleştirmesini öğrenmesine zaman tanımak için ertelenir."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 150632), '''String: "Bebeğin ağlamasına, ses düzeyini ve titreşimi otomatik olarak artırarak tepki verir ve bebeği sakinleştirmeye yardımcı olur."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 150624), '''String: "Akıllı Algılama Sistemi, bebeğin ağlamasına tepki verebilir ve aralarından seçim yapabileceğin, özel olarak tasarlanmış 3 sakinleştirme modu sunar."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 150616), '''String: "Videoları İzle"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 150608), '''String: "Akıllı Algılama Sistemi, dikkatli bir şekilde yalnızca beşik kontrol panelinden etkinleştirilebilecek şekilde tasarlanmıştır. Bu sayede ebeveyn ve bebek bağlı kalır ve sistem dinleyip sakinleştirmeye başlamadan önce bebek kontrol edilmiş olur."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 150600), '''Closure: (dynamic) => String from Function 'm24': static. (0x703267296a64)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 150592), '''String: "Uykunun kesilmeden devam etmesi için sakinleştirici sesler oynatılır. (Not: Akıllı Algılama Sistemi, bu aşamada dikkat kesilir)."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 150584), '''String: "Daha yavaş müzik, bebeğin duyularını rahatlatır ve uyumasını giderek kolaylaştırır. (Not: Akıllı Algılama Sistemi, bu aşamada dikkat kesilir)."''', True)
