	ida_struct.set_member_cmt(ida_struct.get_member(struc, 150320), '''String: "Çeşitli seslerden müziğe ve yatıştırıcı titreşimlere kadar kendi sakinleştirme tercihlerini seç. Ayrıca favorilerini kaydet!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 150312), '''String: "Beşik, bebeğin ağlamasına çeşitli sakinleştirme seçenekleriyle otomatik olarak yanıt verir. 3 özel sakinleştirme modu arasından seçim yapabilirsin."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 150304), '''String: "Luminate Bassinet™\'ine hoş geldin! Bebeğini sakinleştirip uyutmak istediğinde aralarından seçim yapabileceğin birkaç seçeneğin bulunuyor. Ayrıca hoş ışıklandırma özelliklerine de göz atabilirsin!"''', True)
