	ida_struct.set_member_cmt(ida_struct.get_member(struc, 147576), '''String: "Ayarlarını düzenleyebilmen için Lumalou\'nun uyuması gerekiyor. Bir kestirme uykusu başlat... Şşşt... Ardından tüm kontroller senindir."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 147568), '''String: "Lumalou\'yu bir Uyku Arkadaşı ve Uyku Eğitimcisi olarak nasıl kullanabileceğin hakkında daha fazla bilgi edinmek istiyor musun\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 147560), '''String: "Uyanma ve Uyuma saatleri ayarlandıktan sonra Lumalou, çocuklar uzaktan kumandaya bastığında yatakta kalma zamanıysa kırmızı veya yataktan çıkmakta bir sakınca yoksa yeşil yanar."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 147552), '''String: "Uyku Eğitimcisi, çocukların ne zaman yatakta kalmaları gerektiğini ve ne zaman yataktan çıkabileceklerini öğrenmelerine yardımcı olur! Haftanın her günü için farklı Uyuma ve Uyanma saatleri girebilir veya aynı programı tüm günlere uygulayabilirsin."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 147544), '''String: "Ayarları kişiselleştirdikten sonra \"Sakinleştirmeyi Başlat\" düğmesine dokunarak veya uzaktan kumandaya basarak sakinleştirmeyi hemen başlatabilirsin."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 147536), '''Closure: (dynamic) => String from Function 'm7': static. (0x703267297404)''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 147528), '''String: "Lumalou, rutindeki tüm görevleri aydınlatır. Başlamak için uzaktan kumandaya bas, ilk görev belirir. Görevi tamamladıktan sonra eğlenceli ödüller ve rutinde ilerlemek için uzaktan kumandaya bas!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 147520), '''String: "Rutinini Planlama"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 147512), '''String: "Günleri seç ve bir başlangıç saati belirle. Kaydedildiğinde Lumalou, rutini planlanan saat ve günde otomatik olarak başlatacak."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 147504), '''String: "Bir Rutin Oluştur"''', True)
