	ida_struct.set_member_cmt(ida_struct.get_member(struc, 145752), '''String: "Görünüşe bakılırsa burada yenisin! Hadi bu tatlı, küçük tavşanı istediğin gibi ayarlayalım. Hazır mısın\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 145744), '''String: "Tavşanın bir uyku arkadaşı ve uyku eğitimcisi olduğunu biliyor muydun\?"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 145736), '''String: "Tavşanın karnına basıldığında çocuklar, saatin kaç olduğuna göre farklı tepkiler alır... Gündüz: Karnı yeşile döner, bu da kalkma vakti geldi demektir! Gece ve Ara Uyku Zamanı: Karnı kırmızıya döner ve bu da yatakta kalma vakti demektir!"''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 145728), '''String: "Uyku Eğitimcisi, çocukların ne zaman yatakta kalmaları gerektiğini ve ne zaman yataktan çıkabileceklerini öğrenmelerine yardımcı olur! Başlamak için \"Uyku Eğitimcisini Ayarla\" seçeneğini kullan."''', True)
	ida_struct.set_member_cmt(ida_struct.get_member(struc, 145720), '''String: "İsteğe Bağlı Uykuya Geçiş"''', True)
