	ida_struct.set_member_cmt(ida_struct.get_member(struc, 145704), '''String: "Kontroller alanında ışıkları, müzik ve ses seçeneklerini ve Zamanlayıcı ayarlama tercihlerini özelleştirebilirsin."''', True)
